646	// FA3 register-source P (MmaPV_is_RS): build the fp8 A-operand registers from the f32 softmax
647	// probabilities s[64] (C-accumulator layout) WITHOUT the smem scatter+barrier round-trip. Pack each
648	// c-group's 4 f32 ((p,r2) combined, convert_layout_acc_Aregs order) -> P16[c], then permute_Aregs_fp8
649	// (quad __shfl + byte_perm) fixes the register layout to the wgmma A operand. Validated bit-exact vs
650	// the SS path in kernels/fp8_probe.cu (PV-RS). tg=lane&3, group=lane>>2.
651	__device__ __forceinline__ void build_P_rs_fp8(const float (&s)[64], uint32_t (&P16)[16], int tg, int group) {
652	#pragma unroll
653	    for (int c = 0; c < 16; ++c) {
654	        __nv_fp8_e4m3 e0(s[c*4+0]), e1(s[c*4+1]), e2(s[c*4+2]), e3(s[c*4+3]);
655	        P16[c] = (uint32_t)e0.__x | ((uint32_t)e1.__x << 8) | ((uint32_t)e2.__x << 16) | ((uint32_t)e3.__x << 24);
656	    }
657	    const bool lane_03 = (tg == 0 || tg == 3);
658	    const int sel_up = lane_03 ? 0x5410 : 0x1054, sel_lo = lane_03 ? 0x7632 : 0x3276;
659	    const int up = (tg == 0) ? 0 : (tg == 1) ? 3 : (tg == 2) ? 1 : 2;   // upper_map[tg]
660	    const int src_hi = group * 4 + up, src_lo = group * 4 + (up ^ 1);
661	#pragma unroll
662	    for (int u = 0; u < 8; ++u) {
663	        uint32_t upper = P16[2*u + 0], lower = P16[2*u + 1];
664	        uint32_t upper0 = lane_03 ? upper : lower;
665	        uint32_t lower0 = lane_03 ? lower : upper;
666	        upper0 = __shfl_sync(0xffffffffu, upper0, src_hi, 32);
667	        lower0 = __shfl_sync(0xffffffffu, lower0, src_lo, 32);
668	        P16[2*u + 0] = __byte_perm(upper0, lower0, sel_up);
669	        P16[2*u + 1] = __byte_perm(upper0, lower0, sel_lo);
670	    }
671	}
672	// PV with P in REGISTERS (RS A operand): acc_o += P.V over CTA_N keys, A = P16[4kb..4kb+3] per k-block,
673	// B = Vt[dv][key] (smem descriptor). No smem-P scatter/barrier -> enables the QK(i+1)/PV(i) pipeline.
674	// m64n128 for HDV=128, m64n64 for HDV=64 (acc_o[32]).
675	template <int HDV>
676	__device__ __forceinline__ void pv_fp8_rs(float (&acc_o)[HDV/2], const uint32_t (&P16)[16], uint32_t sV_base) {
677	    asm volatile("wgmma.fence.sync.aligned;\n" ::: "memory");
678	#pragma unroll
679	    for (int kb = 0; kb < CTA_N / 32; ++kb) {
680	        uint32_t off = (uint32_t)(kb * 32);
681	        uint64_t dB = make_smem_desc(sV_base + off, SW8_LBO, SW8_SBO, 1);
682	        if constexpr (HDV == 128)
683	            asm volatile(
684	            "{\n.reg .pred p;\n setp.ne.b32 p, %68, 0;\n"
685	            "wgmma.mma_async.sync.aligned.m64n128k32.f32.e4m3.e4m3 " PF_ACC64 ",{%64,%65,%66,%67},%69,p,%70,%71;\n}\n"
686	            : PF_OUT64(acc_o)
687	            : "r"(P16[kb*4+0]),"r"(P16[kb*4+1]),"r"(P16[kb*4+2]),"r"(P16[kb*4+3]),
688	              "r"(1),"l"(dB),"n"(1),"n"(1));
689	        else
690	            asm volatile(
691	            "{\n.reg .pred p;\n setp.ne.b32 p, %36, 0;\n"
692	            "wgmma.mma_async.sync.aligned.m64n64k32.f32.e4m3.e4m3 " PF_ACC32 ",{%32,%33,%34,%35},%37,p,%38,%39;\n}\n"
693	            : PF_OUT32(acc_o, 0)
694	            : "r"(P16[kb*4+0]),"r"(P16[kb*4+1]),"r"(P16[kb*4+2]),"r"(P16[kb*4+3]),
695	              "r"(1),"l"(dB),"n"(1),"n"(1));
696	    }
697	    asm volatile("wgmma.commit_group.sync.aligned;\n" ::: "memory");
698	}
699	// Two adjacent key-cols share a byte pair => one st.shared.u16 (koff8 is even at col=8c+2tg).
700	__device__ __forceinline__ void scatter_P_fp8(const float (&s)[64], uint32_t sP_wg_addr,
701	                                              int warp, int group, int tg) {
702	#pragma unroll
703	    for (int c = 0; c < CTA_N / 8; ++c)
704	#pragma unroll
705	        for (int r = 0; r < 2; ++r) {
706	            int row = warp * 16 + group + r * 8;
707	            int col = 8 * c + 2 * tg;
708	            __nv_fp8_e4m3 a(s[c*4+r*2+0]), b(s[c*4+r*2+1]);
709	            uint16_t packed = (uint16_t)a.__x | ((uint16_t)b.__x << 8);
710	            uint32_t dst = sP_wg_addr + (uint32_t)koff8(row, col);
711	            asm volatile("st.shared.u16 [%0], %1;\n" :: "r"(dst), "h"(packed) : "memory");
712	        }
713	}
714	// cp.async gather (fp8): the producer issues raw 16-byte copies and races STAGES ahead instead of
715	// blocking on each LDG (a synchronous uint4 gather exposes ~56% long_scoreboard at 1 CTA/SM since
716	// there is no other resident CTA to hide it). Completion is tied to an mbarrier via
717	// cp_async_mbar_arrive. Invalid rows (key>=seqlen_k
718	// or padded q) are zeroed synchronously: masked-out keys must still be finite (P=0 * V; a stale fp8
719	// NaN would make 0*NaN=NaN). cp.async can't convert/transpose, so K/Q go straight to the swizzled
720	// tile while V lands in a PLAIN [key][dv] staging tile that a later in-smem pass transposes.
721	template <int HDt>
722	__device__ __forceinline__ void gather_row_k8_cp(__nv_fp8_e4m3* sbase, uint32_t sbase_addr, int row,
723	                                                 const __nv_fp8_e4m3* src, bool valid) {
724	#pragma unroll
725	    for (int c16 = 0; c16 < HDt / 16; ++c16) {
726	        int o = koff8(row, c16 * 16);
727	        if (valid) cp_async_16(sbase_addr + (uint32_t)o, src + c16 * 16);
728	        else       *reinterpret_cast<uint4*>(sbase + o) = make_uint4(0, 0, 0, 0);
729	    }
730	}
731	template <int HDt>
732	__device__ __forceinline__ void gather_row_plain8_cp(__nv_fp8_e4m3* sbase, uint32_t sbase_addr, int row,
733	                                                     const __nv_fp8_e4m3* src, bool valid) {
734	#pragma unroll
735	    for (int c16 = 0; c16 < HDt / 16; ++c16) {
736	        int o = row * HDt + c16 * 16;
737	        if (valid) cp_async_16(sbase_addr + (uint32_t)o, src + c16 * 16);
738	        else       *reinterpret_cast<uint4*>(sbase + o) = make_uint4(0, 0, 0, 0);
739	    }
740	}
741	// Transpose one key column of the PLAIN [key][dv] staging tile into the swizzled K-major sVt[dv][key]
742	// (smem->smem; the global load latency is now hidden by cp.async, this pass only touches smem).
743	template <int HDVt>
744	__device__ __forceinline__ void transpose_v_smem8(__nv_fp8_e4m3* sVt, const __nv_fp8_e4m3* sVst, int key) {
745	#pragma unroll
746	    for (int c16 = 0; c16 < HDVt / 16; ++c16) {
747	        uint4 chunk = *reinterpret_cast<const uint4*>(sVst + key * HDVt + c16 * 16);
748	        const __nv_fp8_e4m3* cv = reinterpret_cast<const __nv_fp8_e4m3*>(&chunk);
749	#pragma unroll
750	        for (int e = 0; e < 16; ++e) sVt[koff8(c16 * 16 + e, key)] = cv[e];
751	    }
752	}
