756	// Gather one row (HDt elems) of K-major data from gmem into the swizzled smem tile (16-bit TC), OR
757	// zero it. TIn is the gmem element type: when TIn==TC (bf16/fp16) it is a raw 16-byte copy (cp.async
758	// or store); when TIn is fp8-e4m3 each 8-elem chunk is loaded, converted to TC (bf16) and stored
759	// (TMA/cp.async can't convert ⇒ fp8 always takes the synchronous convert-store path).
760	template <typename TIn, typename TC, int HDt, int ROWS = CTA_N>
761	__device__ __forceinline__ void gather_row_k(TC* sbase, uint32_t sbase_addr, int row,
762	                                             const TIn* src, bool valid) {
763	#pragma unroll
764	    for (int c8 = 0; c8 < HDt / 8; ++c8) {
765	        int o = koffR<ROWS>(row, c8 * 8);
766	        if (!valid) { *reinterpret_cast<uint4*>(sbase + o) = make_uint4(0, 0, 0, 0); continue; }
767	        if constexpr (std::is_same<TIn, TC>::value) {
768	#if PF_CPASYNC
769	            cp_async_16(sbase_addr + (uint32_t)(o * 2), src + c8 * 8);
770	#else
771	            *reinterpret_cast<uint4*>(sbase + o) = *reinterpret_cast<const uint4*>(src + c8 * 8);
772	#endif
773	        } else {
774	            uint2 raw = *reinterpret_cast<const uint2*>(src + c8 * 8);   // 8 fp8 in ONE coalesced load
775	            const TIn* f = reinterpret_cast<const TIn*>(&raw);
776	            TC tmp[8];
777	#pragma unroll
778	            for (int e = 0; e < 8; ++e) tmp[e] = from_float<TC>(to_float<TIn>(f[e]));
779	            *reinterpret_cast<uint4*>(sbase + o) = *reinterpret_cast<const uint4*>(tmp);

300	    if (win_r >= 0) { int t = qlo + win_r; if (t < hi0) hi0 = t;  t = qhi + win_r; if (t < hi1) hi1 = t; }
301	    // Fast-out for fully-visible tiles (same lever as pf_mask): if every key index this tile spans lies
302	    // within the most-restrictive [lo,hi] of both rows, nothing is masked -> skip the per-element ALU on
303	    // the QK->next-QK critical path. lo = max(lo0,lo1) (tightest left), hi = min(hi0,hi1) (tightest right).
304	    const int kmax = col0 + CN - 1;
305	    const int lo = lo0 > lo1 ? lo0 : lo1, hi = hi0 < hi1 ? hi0 : hi1;
306	    if (col0 >= lo && kmax <= hi) return;
307	#pragma unroll
308	    for (int c = 0; c < CN / 8; ++c) {
309	        int k0 = col0 + 8 * c + 2 * tg;
310	        if (k0     < lo0 || k0     > hi0) s[c*4+0] = -INFINITY;
311	        if (k0 + 1 < lo0 || k0 + 1 > hi0) s[c*4+1] = -INFINITY;
312	        if (k0     < lo1 || k0     > hi1) s[c*4+2] = -INFINITY;
313	        if (k0 + 1 < lo1 || k0 + 1 > hi1) s[c*4+3] = -INFINITY;
314	    }
315	}
316	// Hardware tanh approximation (matches cutlass::fast_tanh / FA3's softcap path): a single SFU
317	// instruction vs the ~20-instruction libdevice tanhf -- softcap feeds exp2 so approx is ample.
318	__device__ __forceinline__ float fast_tanh(float x) {
319	    float r; asm("tanh.approx.f32 %0, %1;" : "=f"(r) : "f"(x)); return r;
320	}
321	// Logit softcap, applied to the RAW Q.K^T before masking. softmax_stats later multiplies by `scale`,
322	// so store softcap*tanh(raw*scale/softcap)/scale to get an effective logit of softcap*tanh(raw*scale/softcap).
323	template <int CN = CTA_N>
324	__device__ __forceinline__ void pf_softcap(float (&s)[CN/2], float scale, float softcap) {
325	    const float a = scale / softcap;       // raw -> tanh argument
326	    const float b = softcap / scale;       // tanh -> stored value (softmax_stats re-applies *scale)
327	#pragma unroll
328	    for (int i = 0; i < CN / 2; ++i) s[i] = fast_tanh(s[i] * a) * b;
329	}
