56	// Params: all strides are IN ELEMENTS.
57	template <typename TIn, typename TOut>
58	struct Params {
59	  const TIn* q; const TIn* k; const TIn* v;
60	  TOut* o; float* lse;
61	  const int* cu_q;          // (b+1) or null
62	  const int* cu_k;          // (b+1) or null (non-paged)
63	  const int* seqused_k;     // (b) or null (paged)
64	  const int* page_table;    // (b, max_blocks) or null
65	  const float* q_descale; const float* k_descale; const float* v_descale;  // (b, hkv) or null
66	  int ds_b, ds_h;           // descale strides IN ELEMENTS (broadcast-safe; 0 for stride-0 tensors)
67	  long q_row, q_head, k_row, k_head, v_row, v_head, o_row, o_head;
68	  int b, hq, hkv, hd, hdv, total_q, block_size, page_stride;
69	  float scale, softcap;
70	  int win_l, win_r; bool causal;
71	};
