73	template <typename TIn, typename TOut>
74	__global__ void attn_kernel(Params<TIn, TOut> p) {
75	  const int warp = (blockIdx.x * blockDim.x + threadIdx.x) >> 5;
76	  const int lane = threadIdx.x & 31;
77	  const long total_pairs = (long)p.total_q * p.hq;
78	  if (warp >= total_pairs) return;
79	  const int q_idx = warp / p.hq;
80	  const int head  = warp % p.hq;
81	  const int hk    = head / (p.hq / p.hkv);
82	
83	  // locate batch b s.t. cu_q[b] <= q_idx < cu_q[b+1]
84	  int b = 0;
85	  while (b + 1 <= p.b && p.cu_q[b + 1] <= q_idx) ++b;
86	  const int q_in_seq = q_idx - p.cu_q[b];
87	  const int sq = p.cu_q[b + 1] - p.cu_q[b];
88	  const int klen = p.seqused_k ? p.seqused_k[b] : (p.cu_k[b + 1] - p.cu_k[b]);
89	  const int q_abs = klen - sq + q_in_seq;   // causal alignment: last query <-> last key
90	
91	  // Descale is stride-aware (vLLM passes a BROADCAST (b,hkv) tensor with stride [0,0] and one
92	  // physical element -- dense indexing would read out of bounds). Only non-null for fp8.
93	  const long ds_idx = (long)b * p.ds_b + (long)hk * p.ds_h;
94	  float qd = p.q_descale ? p.q_descale[ds_idx] : 1.f;
95	  float kd = p.k_descale ? p.k_descale[ds_idx] : 1.f;
96	  float vd = p.v_descale ? p.v_descale[ds_idx] : 1.f;
97	  const float qk_scale = p.scale * qd * kd;
98	
99	  // load q row into per-lane registers
100	  const int per = (p.hd + 31) / 32;
101	  float qreg[(MAX_HD + 31) / 32];
102	  const TIn* qp = p.q + (long)q_idx * p.q_row + (long)head * p.q_head;
103	  #pragma unroll
104	  for (int e = 0; e < per; ++e) { int d = lane + e * 32; qreg[e] = d < p.hd ? to_float<TIn>(qp[d]) : 0.f; }
105	
106	  const int perv = (p.hdv + 31) / 32;
107	  float acc[(MAX_HD + 31) / 32];
108	  #pragma unroll
109	  for (int e = 0; e < perv; ++e) acc[e] = 0.f;
110	  float m = -INFINITY, l = 0.f;
111	
112	  for (int j = 0; j < klen; ++j) {
113	    bool masked = false;
114	    if (p.causal && j > q_abs) masked = true;
115	    if (p.win_l >= 0 && j < q_abs - p.win_l) masked = true;
116	    if (p.win_r >= 0 && j > q_abs + p.win_r) masked = true;
117	    if (masked) continue;
118	
119	    long krow;
120	    if (p.page_table) {
121	      int blk = p.page_table[(long)b * p.page_stride + j / p.block_size];
122	      krow = ((long)blk * p.block_size + (j % p.block_size));
123	    } else {
124	      krow = (long)p.cu_k[b] + j;
125	    }
126	    const TIn* kp = p.k + krow * p.k_row + (long)hk * p.k_head;
127	    float dot = 0.f;
128	    #pragma unroll
129	    for (int e = 0; e < per; ++e) { int d = lane + e * 32; if (d < p.hd) dot += qreg[e] * to_float<TIn>(kp[d]); }
130	    float s = warp_reduce_sum(dot) * qk_scale;
131	    if (p.softcap > 0.f) s = p.softcap * tanhf(s / p.softcap);
132	
133	    float m_new = fmaxf(m, s);
134	    float corr = __expf(m - m_new);
135	    float pj = __expf(s - m_new);
136	    l = l * corr + pj;
137	    const TIn* vp = p.v + krow * p.v_row + (long)hk * p.v_head;
138	    #pragma unroll
139	    for (int e = 0; e < perv; ++e) { int d = lane + e * 32; float vv = d < p.hdv ? to_float<TIn>(vp[d]) * vd : 0.f; acc[e] = acc[e] * corr + pj * vv; }
140	    m = m_new;
141	  }
142	
143	  TOut* op = p.o + (long)q_idx * p.o_row + (long)head * p.o_head;
144	  float inv = l > 0.f ? 1.f / l : 0.f;
145	  #pragma unroll
146	  for (int e = 0; e < perv; ++e) { int d = lane + e * 32; if (d < p.hdv) op[d] = from_float<TOut>(acc[e] * inv); }
147	  if (lane == 0) p.lse[(long)head * p.total_q + q_idx] = (l > 0.f) ? (m + logf(l)) : (-INFINITY);
148	}
